/* audio/effects/reverb.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../../context.js";

export function install(P) {


  function makeReverbImpulse(context, decay) {
    const seconds = P.clamp(Number(decay) || P.FX_RANGES.reverbDecay.fallback, P.FX_RANGES.reverbDecay.min, P.FX_RANGES.reverbDecay.max);
    const length = Math.max(1, Math.floor(context.sampleRate * seconds));
    const impulse = context.createBuffer(2, length, context.sampleRate);
    // Slightly steeper tails at longer decays keep the end from sounding boxy.
    const exponent = 1.9 + seconds * 0.3;
    for (let channel = 0; channel < 2; channel++) {
      const data = impulse.getChannelData(channel);
      for (let i = 0; i < length; i++) {
        const t = i / length;
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, exponent);
      }
    }
    return impulse;
  }
  Object.assign(P, { makeReverbImpulse });
}
